// Turns validated canonical content into what publishes (docs/contract.md,
// section 8): the generated file header, the published registry items, the
// registry index and the data the site renders. Deterministic: no clocks, so
// two builds of one commit produce identical output.
import { demoFor, includeBeta, isShown, kindOf } from "./content.mjs";
import {
  CLI_NAME,
  cliCommand,
  ICON_ORDER,
  ICON_SETS,
  itemUrl,
  NAMESPACE,
  NPM_LIBRARY,
  namespaceCommand,
  npmSubpath,
  PRIMITIVE_ORDER,
  PRIMITIVES,
  packageName,
  pageUrl,
  SHADCN_ITEM_SCHEMA,
  SHADCN_REGISTRY_SCHEMA,
  SITE_URL,
  shadcnCommand,
} from "./naming.mjs";

export const HEADER_MARK = "@dfl-header";
const NPM_KINDS = new Set(["component", "hook", "lib"]);
const TARGET_DIRS = {
  "registry:ui": "components/ui",
  "registry:component": "components",
  "registry:block": "components",
  "registry:hook": "hooks",
  "registry:lib": "lib",
};

/** Names a module exports at runtime (not types). */
export function exportedNames(content) {
  const names = new Set();
  for (const match of content.matchAll(/export\s*\{([^}]*)\}/g)) {
    for (const part of match[1].split(",")) {
      const clean = part.trim();
      if (clean && !clean.startsWith("type ")) {
        names.add(
          clean
            .split(/\s+as\s+/)
            .pop()
            .trim(),
        );
      }
    }
  }
  for (const match of content.matchAll(
    /export\s+(?:async\s+)?(?:function|const|let|class)\s+([A-Za-z0-9_$]+)/g,
  )) {
    names.add(match[1]);
  }
  return [...names];
}

export function targetPath(file) {
  if (file.target) {
    return file.target.replace(/^@(ui|components|lib|hooks)\//, (_, k) =>
      k === "ui" ? "components/ui/" : `${k}/`,
    );
  }
  return `${TARGET_DIRS[file.type] ?? "components"}/${file.path.split("/").pop()}`;
}

function commandsFor(meta, variant, exports) {
  const kind = kindOf(meta);
  const commands = {
    shadcn: shadcnCommand(variant.name),
    namespace: namespaceCommand(variant.name),
  };
  if (kind === "component") {
    commands.cli = cliCommand({
      component: meta.name,
      style: variant.style,
      primitive: variant.primitive,
      iconSet: variant.iconSet,
    });
  }
  if (kind === "base") {
    commands.shadcn = `npx shadcn@latest init ${itemUrl(variant.name)}`;
  }
  if (NPM_KINDS.has(kind)) {
    const subpath = npmSubpath({
      component: meta.name,
      style: variant.style,
      primitive: variant.primitive,
      iconSet: variant.iconSet,
    });
    commands.npm = `npm i ${NPM_LIBRARY}`;
    commands.importPath = `${NPM_LIBRARY}/${subpath}`;
    commands.importLine = `import { ${exports.join(", ")} } from "${NPM_LIBRARY}/${subpath}";`;
  }
  return commands;
}

function wrap(text, width, indent) {
  const words = text.split(/\s+/).filter(Boolean);
  const lines = [];
  let line = "";
  for (const word of words) {
    if (line && `${line} ${word}`.length > width) {
      lines.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) {
    lines.push(line);
  }
  return lines.map((l, i) => (i === 0 ? l : `${indent}${l}`));
}

/** The LLM-oriented provenance and usage header prepended to every file. */
export function headerFor(meta, variant, item, credits, commands) {
  const clean = (s) => String(s).replaceAll("*/", "* /");
  const label = [
    variant.style ? (variant.label ?? variant.style) : null,
    PRIMITIVES[variant.primitive]?.package
      ? PRIMITIVES[variant.primitive].label
      : null,
    ICON_SETS[variant.iconSet]?.package
      ? ICON_SETS[variant.iconSet].label
      : null,
  ]
    .filter(Boolean)
    .join(", ");
  const source =
    meta.source.repo === "private source"
      ? `private source @ ${meta.source.commit.slice(0, 12)}`
      : `${meta.source.repo} @ ${meta.source.commit.slice(0, 12)}${meta.source.path ? ` (${meta.source.path})` : ""}`;
  const requires = [
    ...(item.dependencies ?? []).map(packageName),
    ...(item.registryDependencies?.length
      ? [`registry: ${item.registryDependencies.join(", ")}`]
      : []),
  ];
  const creditText = meta.credits
    .map((id) => {
      const c = credits.get(id);
      return c ? `${id} ${c.title} (${c.license})` : id;
    })
    .join("; ");
  const rows = [
    [HEADER_MARK, "v1, generated by labs.designfrom.com at build time"],
    ["Item", `${variant.name} (${meta.title}${label ? `: ${label}` : ""})`],
    ["What", meta.description],
    [
      "Status",
      `${variant.status}. License: ${meta.license}. Author: ${meta.author}`,
    ],
    ["Source", source],
    ["Credits", creditText],
    ...(meta.attribution ? [["Attribution", meta.attribution]] : []),
    ["Install", commands.shadcn],
    ["", commands.namespace],
    ...(commands.cli ? [["", commands.cli]] : []),
    ...(commands.importLine
      ? [["", `${commands.npm}, then ${commands.importLine}`]]
      : []),
    ...(requires.length ? [["Requires", requires.join(", ")]] : []),
    ["Docs", `${pageUrl(meta.name)} (index: ${SITE_URL}/llms.txt)`],
  ];
  const lines = ["/**"];
  const WRAP = new Set(["What", "Credits", "Attribution", "Status"]);
  for (const [key, value] of rows) {
    const head = key ? `${key}: ` : "  ";
    const text = clean(value);
    const wrapped = WRAP.has(key)
      ? wrap(text, 74 - head.length, "   ")
      : [text];
    lines.push(` * ${head}${wrapped[0] ?? ""}`);
    for (const rest of wrapped.slice(1)) {
      lines.push(` * ${rest}`);
    }
  }
  lines.push(" */");
  return lines.join("\n");
}

/**
 * Inserts the header right after the import block (after "use client" when
 * there are no imports). The shadcn CLI drops comments that sit above the
 * first import, so a header placed there would never reach users.
 */
export function withHeader(content, header) {
  if (content.includes(HEADER_MARK)) {
    return content;
  }
  const importRe = /^import\s(?:[^;]*?\sfrom\s*)?["'][^"']+["'];?[ \t]*$/gm;
  let end = -1;
  for (const match of content.matchAll(importRe)) {
    end = match.index + match[0].length;
  }
  if (end === -1) {
    const directive = /^\s*["']use (client|server)["'];?[ \t]*$/m.exec(content);
    end = directive ? directive.index + directive[0].length : 0;
  }
  if (end === 0) {
    return `${header}\n\n${content}`;
  }
  return `${content.slice(0, end)}\n\n${header}${content.slice(end)}`;
}

/** Labs item names and @designfrom/<name> become absolute URLs. */
function rewriteRegistryDeps(deps, labsNames) {
  return deps.map((dep) => {
    const bare = dep.startsWith(`${NAMESPACE}/`)
      ? dep.slice(NAMESPACE.length + 1)
      : dep;
    return labsNames.has(bare) ? itemUrl(bare) : dep;
  });
}

/** The registry item as served at /r/<name>.json. */
export function publishedItem(entry, variant, credits, labsNames) {
  const { meta } = entry;
  const item = entry.items.get(variant.name);
  const exports = (item.files ?? []).flatMap((f) => exportedNames(f.content));
  const commands = commandsFor(meta, variant, exports);
  const header = headerFor(meta, variant, item, credits, commands);
  const out = {
    ...item,
    $schema: SHADCN_ITEM_SCHEMA,
    categories: [...new Set([meta.category, ...(item.categories ?? [])])],
    docs: `${item.docs}\n\nDocs and every variant: ${pageUrl(meta.name)}`,
    meta: {
      status: variant.status,
      license: meta.license,
      author: meta.author,
      source: meta.source,
      credits: meta.credits,
      component: meta.name,
      kind: kindOf(meta),
      primitive: variant.primitive,
      iconSet: variant.iconSet,
      ...(variant.style ? { style: variant.style } : {}),
      page: pageUrl(meta.name),
    },
  };
  if (item.registryDependencies) {
    out.registryDependencies = rewriteRegistryDeps(
      item.registryDependencies,
      labsNames,
    );
  }
  if (item.files) {
    out.files = item.files.map((file) => ({
      ...file,
      content: withHeader(file.content, header),
    }));
  }
  return { item: out, commands, exports, header };
}

/** /r/registry.json: every published item, without file contents. */
export function registryIndex(published) {
  return {
    $schema: SHADCN_REGISTRY_SCHEMA,
    name: "designfrom",
    homepage: SITE_URL,
    items: published.map(({ item }) => ({
      ...item,
      $schema: undefined,
      files: item.files?.map(({ content: _content, ...rest }) => rest),
    })),
  };
}

function creditView(credits, id) {
  const c = credits.get(id);
  return c
    ? {
        id,
        title: c.title,
        author: c.author,
        license: c.license,
        url: c.url ?? null,
      }
    : { id, title: id, author: "", license: "", url: null };
}

/**
 * Everything the site renders. Only entries with at least one published
 * variant appear; each lists every variant with its published state so the
 * switcher can mark unavailable combinations honestly.
 */
export function siteData(components, credits, projects, beta = includeBeta()) {
  const labsNames = new Set(components.flatMap((c) => [...c.items.keys()]));
  const entries = [];
  const published = [];
  for (const entry of components) {
    const { meta } = entry;
    if (!(meta?.status === "ready" || (beta && meta?.status === "beta"))) {
      continue;
    }
    const variants = [];
    for (const variant of meta.variants) {
      const live =
        isShown(meta, variant, beta) && entry.items.has(variant.name);
      const view = {
        name: variant.name,
        primitive: variant.primitive,
        iconSet: variant.iconSet,
        style: variant.style ?? null,
        label: variant.label ?? null,
        status: variant.status,
        published: live,
      };
      if (live) {
        const result = publishedItem(entry, variant, credits, labsNames);
        published.push({ ...result, entry, variant });
        Object.assign(view, {
          demo: demoFor(meta, variant),
          commands: result.commands,
          exports: result.exports,
          type: result.item.type,
          dependencies: result.item.dependencies ?? [],
          registryDependencies: result.item.registryDependencies ?? [],
          cssVars: result.item.cssVars ?? null,
          font: result.item.font ?? null,
          config: result.item.config ?? null,
          docs: result.item.docs,
          files: (result.item.files ?? []).map((f) => ({
            path: f.path,
            target: targetPath(f),
            type: f.type,
            content: f.content,
          })),
        });
      }
      variants.push(view);
    }
    if (!variants.some((v) => v.published)) {
      continue;
    }
    const styles = [
      ...new Map(
        meta.variants.map((v) => [
          v.style ?? null,
          v.label ?? (v.style ? v.style : "Default"),
        ]),
      ).entries(),
    ].map(([value, label]) => ({ value, label }));
    const usesPrimitives = meta.variants.some((v) => v.primitive !== "none");
    // An entry that mixes a primitive-free default with primitive variants
    // offers "none" too, so the default can be chosen again (P-222).
    const primitives = usesPrimitives
      ? [
          ...(meta.variants.some((v) => v.primitive === "none")
            ? ["none"]
            : []),
          ...PRIMITIVE_ORDER,
        ]
      : [];
    const usesIcons = meta.variants.some((v) => v.iconSet !== "none");
    entries.push({
      name: meta.name,
      sourceId: entry.sourceId,
      status: meta.status,
      kind: kindOf(meta),
      title: meta.title,
      description: meta.description,
      category: meta.category,
      label: meta.label ?? null,
      tags: meta.tags ?? [],
      author: meta.author,
      license: meta.license,
      attribution: meta.attribution ?? null,
      source: meta.source,
      date: meta.date,
      props: meta.props ?? [],
      a11y: meta.a11y ?? [],
      usage: meta.usage ?? null,
      stage: meta.stage ?? null,
      tile: meta.tile ?? null,
      loop: meta.loop ?? null,
      preview: meta.preview ? `${entry.rel}/${meta.preview}` : null,
      credits: meta.credits.map((id) => creditView(credits, id)),
      defaultVariant: meta.defaultVariant,
      dimensions: {
        styles,
        primitives,
        iconSets: usesIcons ? ICON_ORDER : [],
      },
      variants,
    });
  }
  return {
    site: {
      url: SITE_URL,
      npm: NPM_LIBRARY,
      cli: CLI_NAME,
      namespace: NAMESPACE,
    },
    labels: {
      primitives: Object.fromEntries(
        Object.entries(PRIMITIVES).map(([k, v]) => [k, v.label]),
      ),
      iconSets: Object.fromEntries(
        Object.entries(ICON_SETS).map(([k, v]) => [k, v.label]),
      ),
    },
    entries,
    credits: [...credits.values()]
      .filter((c) => c.visibility === "public")
      .map((c) => ({
        id: c.id,
        title: c.title,
        author: c.author,
        kind: c.kind,
        license: c.license,
        url: c.url,
      })),
    projects,
    published,
  };
}
